/** Integrated TV Access workflow. All ADB work follows an explicit button and confirmation. */
public final class AccessActivity extends Activity {
 private SettingsStore prefs;private ListView list;private TextView state;private Button apply;
 private final List<Entry> entries=new ArrayList<>();private final Set<String> selected=new LinkedHashSet<>();
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private boolean busy;private String appearance;private AlertDialog progress;
 static final class Entry {final String pkg,label,component;Entry(String p,String l,String c){pkg=p;label=l;component=c;}}
 private String w(String ru,String en){return Ui.word(this,ru,en);}
 protected void onCreate(Bundle saved){appearance=Ui.prepare(this);super.onCreate(saved);Ui.bars(this);prefs=new SettingsStore(this);prefs.data.edit().remove("restricted_return").apply();if(saved!=null){ArrayList<String> ids=saved.getStringArrayList("selected");if(ids!=null)selected.addAll(ids);}
  LinearLayout body=new LinearLayout(this);body.setOrientation(1);body.setPadding(Ui.dp(this,24),Ui.dp(this,16),Ui.dp(this,24),Ui.dp(this,12));Ui.backdrop(this,body);setContentView(body);body.addView(Ui.label(this,w("Снять ограничение доступа к специальным возможностям — TV Access","Remove Accessibility access restriction — TV Access"),22));
  TextView help=Ui.label(this,Build.VERSION.SDK_INT<33?w("Выберите службу и нажмите первую кнопку «Включить через ADB». Системный список специальных возможностей для этого не нужен. На этой версии Android ограничение Android 13 отсутствует.","Select a service and choose the first button, Enable through ADB. The system Accessibility list is not required. This Android version has no Android 13 restricted-settings gate."):w("Выберите службы, затем нажмите «Включить через ADB». Уже включённые службы сохранятся. Снятие ограничения — отдельное действие для Android 13 и новее.","Select services, then Enable through ADB. Existing enabled services are preserved. Allow restricted settings is a separate action for Android 13 and later."),16);help.setPadding(0,Ui.dp(this,10),0,Ui.dp(this,10));body.addView(help);
  LinearLayout buttons=new LinearLayout(this);Button connect=Ui.tvButton(this,w("Подключение ADB","ADB connection"));apply=Ui.tvButton(this,w("Снять для выбранных","Allow selected apps"));Button enable=Ui.tvButton(this,w("Включить через ADB","Enable through ADB"));enable.setOnClickListener(v->confirmEnable());Button settings=Ui.tvButton(this,w("Специальные возможности","Accessibility settings"));for(Button b:new Button[]{enable,connect,apply,settings}){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,Ui.dp(this,54),1);p.rightMargin=Ui.dp(this,6);b.setId(View.generateViewId());buttons.addView(b,p);}body.addView(buttons);connect.setOnClickListener(v->connection());apply.setOnClickListener(v->confirm());settings.setOnClickListener(v->Controls.openAccessibility(this));state=Ui.label(this,"",14);state.setPadding(0,Ui.dp(this,8),0,Ui.dp(this,8));body.addView(state);
  list=new ListView(this);list.setId(View.generateViewId());list.setNextFocusUpId(enable.getId());list.setOnKeyListener((view,key,event)->{if(key==KeyEvent.KEYCODE_DPAD_UP&&event.getAction()==KeyEvent.ACTION_DOWN&&list.getSelectedItemPosition()<=0){enable.requestFocus();return true;}return false;});for(Button b:new Button[]{enable,connect,apply,settings})b.setNextFocusDownId(list.getId());list.setCacheColorHint(android.graphics.Color.TRANSPARENT);list.setSelector(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));list.setOnFocusChangeListener((view,focused)->list.setSelector(focused?Ui.selector(this):new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT)));if(Build.VERSION.SDK_INT>=26)list.setDefaultFocusHighlightEnabled(false);list.setAdapter(new BaseAdapter(){public int getCount(){return entries.size();}public Object getItem(int p){return entries.get(p);}public long getItemId(int p){return entries.get(p).component.hashCode();}public boolean hasStableIds(){return true;}public View getView(int p,View reuse,ViewGroup parent){LinearLayout row=reuse instanceof LinearLayout?(LinearLayout)reuse:newRow();Entry e=entries.get(p);AppCatalog.get(AccessActivity.this).image(e.pkg,(ImageView)row.getChildAt(0));LinearLayout text=(LinearLayout)row.getChildAt(1);((TextView)text.getChildAt(0)).setText(e.label);((TextView)text.getChildAt(1)).setText(e.component);row.getChildAt(2).setVisibility(selected.contains(e.component)?View.VISIBLE:View.INVISIBLE);row.setContentDescription(e.label+(selected.contains(e.component)?w(", выбрано",", selected"):""));return row;}});list.setOnItemClickListener((parent,v,p,id)->{if(busy)return;String component=entries.get(p).component;if(!selected.add(component))selected.remove(component);((BaseAdapter)list.getAdapter()).notifyDataSetChanged();update();});body.addView(list,new LinearLayout.LayoutParams(-1,0,1));load();
 }
 private LinearLayout newRow(){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(Ui.dp(this,12),Ui.dp(this,6),Ui.dp(this,12),Ui.dp(this,6));ImageView icon=new ImageView(this);icon.setScaleType(ImageView.ScaleType.FIT_CENTER);row.addView(icon,new LinearLayout.LayoutParams(Ui.dp(this,40),Ui.dp(this,40)));LinearLayout text=new LinearLayout(this);text.setOrientation(1);text.setPadding(Ui.dp(this,12),0,Ui.dp(this,8),0);text.addView(Ui.label(this,"",18));TextView detail=Ui.label(this,"",13);detail.setTextColor(Ui.muted(this));text.addView(detail);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));row.addView(new Glyph(this,"check"),new LinearLayout.LayoutParams(Ui.dp(this,26),Ui.dp(this,26)));return row;}
 static Set<String> packages(Context c){Set<String> found=new HashSet<>();for(ResolveInfo r:c.getPackageManager().queryIntentServices(new Intent("android.accessibilityservice.AccessibilityService"),PackageManager.MATCH_DISABLED_COMPONENTS)){ServiceInfo s=r.serviceInfo;if(s!=null&&"android.permission.BIND_ACCESSIBILITY_SERVICE".equals(s.permission))found.add(s.packageName);}return found;}
 static LinkedHashMap<String,Entry> services(Context context){LinkedHashMap<String,Entry> result=new LinkedHashMap<>();PackageManager pm=context.getPackageManager();for(ResolveInfo r:pm.queryIntentServices(new Intent("android.accessibilityservice.AccessibilityService"),PackageManager.MATCH_DISABLED_COMPONENTS)){ServiceInfo service=r.serviceInfo;if(service==null||!"android.permission.BIND_ACCESSIBILITY_SERVICE".equals(service.permission))continue;String id=AccessibilitySettings.component(new ComponentName(service.packageName,service.name).flattenToString()),app=String.valueOf(pm.getApplicationLabel(service.applicationInfo)),name=String.valueOf(service.loadLabel(pm));result.put(id,new Entry(service.packageName,app+(app.equals(name)?"":" — "+name),id));}return result;}
 private void load(){worker.execute(()->{try{LinkedHashMap<String,Entry> available=services(this);ArrayList<Entry> found=new ArrayList<>(available.values());java.text.Collator order=java.text.Collator.getInstance(getResources().getConfiguration().locale);Collections.sort(found,(a,b)->a.component.equals(b.component)?0:a.pkg.equals(getPackageName())&&!b.pkg.equals(getPackageName())?-1:b.pkg.equals(getPackageName())&&!a.pkg.equals(getPackageName())?1:order.compare(a.label,b.label));main.post(()->{if(isFinishing()||isDestroyed())return;entries.clear();entries.addAll(found);selected.retainAll(available.keySet());((BaseAdapter)list.getAdapter()).notifyDataSetChanged();update();list.requestFocus();});}catch(RuntimeException error){main.post(()->{if(!isFinishing()&&!isDestroyed())state.setText(w("Не удалось прочитать список служб: ","Could not read services: ")+error.getMessage());});}});}
 private String endpoint(){return prefs.text("access_endpoint",prefs.text("expert_endpoint","127.0.0.1:5555"));}
 private void update(){state.setText("ADB · "+endpoint()+" · "+w("Выбрано: ","Selected: ")+selected.size()+"/"+entries.size()+(Build.VERSION.SDK_INT<33?w(" · Для включения нажмите «Включить через ADB»"," · Choose Enable through ADB to activate services"):""));apply.setText(w("Снять для выбранных","Allow selected apps")+(selected.isEmpty()?"":" ("+selected.size()+")"));}
 private void connection(){if(busy)return;ActionSheet.show(this,w("Подключение TV Access","TV Access connection"),new ActionSheet.Item(w("Адрес ADB: ","ADB address: ")+endpoint(),"tune",this::address),new ActionSheet.Item(w("Как подключиться","Connection guide"),"info",this::guide),new ActionSheet.Item(w("Параметры разработчика","Developer options"),"settings",this::developer),new ActionSheet.Item(w("Отключить выбранные службы","Disable selected services"),"close",this::confirmDisable),new ActionSheet.Item(w("Проверить подключение","Test connection"),"replace",()->run(0,new ArrayList<>())));}
 private void developer(){if(!Ui.launch(this,new Intent("android.settings.APPLICATION_DEVELOPMENT_SETTINGS"))&&!Ui.launch(this,new Intent("android.settings.DEVICE_INFO_SETTINGS")))Ui.toast(this,"Откройте настройки → Об устройстве → Сборка","Open Settings → About → Build");}
 private void guide(){new AlertDialog.Builder(this).setTitle(w("Подключение ADB","ADB connection")).setMessage(w("1. Если параметры разработчика скрыты, откройте Об устройстве и нажмите Сборка семь раз.\n\n2. Включите отладку по сети / ADB по TCP/IP. Одна отладка USB не всегда открывает сетевой порт.\n\n3. Укажите адрес этого телевизора, обычно 127.0.0.1:5555, и нажмите Проверить подключение. Разрешите системный запрос RSA.\n\n4. Если сетевого ADB нет, может понадобиться однократная adb tcpip 5555 с компьютера по USB. Сопряжение кодом / TLS не поддерживается.\n\n5. Выберите нужные службы. «Снять для выбранных» меняет только ограничение Android 13+. «Включить через ADB» включает выбранные службы с отдельным подтверждением и проверкой, сохраняя ранее включённые. Системный список служб для этого не требуется.","1. If Developer options is hidden, open About and press Build seven times.\n\n2. Enable network debugging / ADB over TCP/IP. USB debugging alone may not open a network port.\n\n3. Enter this TV's address, usually 127.0.0.1:5555, then Test connection. Approve the system RSA prompt.\n\n4. If network ADB is unavailable, a one-time adb tcpip 5555 over USB from a computer may be needed. Pairing codes / TLS are not supported.\n\n5. Select the needed services. Allow selected apps changes only the Android 13+ gate. Enable through ADB activates selected services after a separate confirmation and readback, preserving existing services. The system service-list screen is not required.")).setPositiveButton("OK",null).setNeutralButton(w("Параметры разработчика","Developer options"),(d,which)->developer()).show();}
 private void address(){EditText input=new EditText(this);input.setSingleLine();input.setText(endpoint());AlertDialog dialog=new AlertDialog.Builder(this).setTitle(w("Адрес:порт этого устройства","This device's address:port")).setView(input).setNegativeButton(w("Отмена","Cancel"),null).setPositiveButton(w("Сохранить","Save"),null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(b->{try{String value=input.getText().toString().trim();AdbWire.endpoint(value);prefs.data.edit().putString("access_endpoint",value).apply();update();dialog.dismiss();}catch(IllegalArgumentException e){input.setError(w("Введите корректный адрес:порт","Enter a valid address:port"));}}));dialog.show();}
 private void confirm(){if(busy)return;if(Build.VERSION.SDK_INT<33){new AlertDialog.Builder(this).setTitle(w("Ограничение не требуется снимать","No restriction to remove")).setMessage(w("ACCESS_RESTRICTED_SETTINGS появился в Android 13. Для включения выбранной службы используйте отдельную кнопку «Включить через ADB», даже если прошивка скрыла список служб.","ACCESS_RESTRICTED_SETTINGS was added in Android 13. Use the separate Enable through ADB button to activate selected services, including when firmware hides the service list.")).setPositiveButton("OK",null).show();return;}if(selected.isEmpty()){Ui.toast(this,"Сначала выберите приложения","Select apps first");return;}ArrayList<String> targets=new ArrayList<>(selected);StringBuilder names=new StringBuilder();for(Entry e:entries)if(targets.contains(e.component))names.append(e.label).append("\n").append(e.pkg).append("\n\n");new AlertDialog.Builder(this).setTitle(w("Разрешить ограниченные настройки?","Allow restricted settings?")).setMessage(names+w("Будет изменён только допуск выбранных приложений. Службы автоматически не включаются.","Only selected apps' allowance will change. Services will not be enabled automatically.")).setNegativeButton(w("Отмена","Cancel"),null).setPositiveButton(w("Разрешить","Allow"),(d,which)->run(1,targets)).show();}
 private void confirmEnable(){if(busy)return;if(selected.isEmpty()){Ui.toast(this,"Сначала выберите службы","Select services first");return;}ArrayList<String> targets=new ArrayList<>(selected);StringBuilder names=new StringBuilder();for(Entry e:entries)if(targets.contains(e.component))names.append(e.label).append("\n").append(e.component).append("\n\n");new AlertDialog.Builder(this).setTitle(w("Включить выбранные службы через ADB?","Enable selected services through ADB?")).setMessage(names+w("Выбранные службы получат доступ специальных возможностей. Они будут добавлены к уже включённым службам. На Android 13+ сначала будет снято ограничение только у выбранных приложений.","Selected services will receive Accessibility access and be added to existing enabled services. On Android 13+, restricted settings will first be allowed only for selected apps.")).setNegativeButton(w("Отмена","Cancel"),null).setPositiveButton(w("Включить","Enable"),(d,which)->run(2,targets)).show();}
 private void confirmDisable(){if(busy)return;if(selected.isEmpty()){Ui.toast(this,"Сначала выберите службы","Select services first");return;}ArrayList<String> targets=new ArrayList<>(selected);new AlertDialog.Builder(this).setTitle(w("Отключить выбранные службы?","Disable selected services?")).setMessage(w("Доступ специальных возможностей будет отключён только у выбранных служб. Остальные включённые службы сохранятся.\n\n","Accessibility access will be turned off only for selected services. Other enabled services will be preserved.\n\n")+targets.toString()).setNegativeButton(w("Отмена","Cancel"),null).setPositiveButton(w("Отключить","Disable"),(d,which)->run(3,targets)).show();}
 private boolean frameworkEnabled(Collection<String> targets){Set<String> enabled=new HashSet<>();android.view.accessibility.AccessibilityManager manager=(android.view.accessibility.AccessibilityManager)getSystemService(ACCESSIBILITY_SERVICE);if(manager==null)return false;for(android.accessibilityservice.AccessibilityServiceInfo info:manager.getEnabledAccessibilityServiceList(android.accessibilityservice.AccessibilityServiceInfo.FEEDBACK_ALL_MASK))try{if(info.getId()!=null)enabled.add(AccessibilitySettings.component(info.getId()));}catch(IllegalArgumentException ignored){}return enabled.containsAll(targets);}
 private void run(int mode,List<String> targets){if(busy)return;busy=true;String address=endpoint();progress=new AlertDialog.Builder(this).setTitle(w("TV Access: подключение","TV Access: connecting")).setMessage(w("Подтвердите запрос отладки RSA на этом телевизоре, если он появится.","Approve the RSA debugging prompt on this TV if it appears.")).setCancelable(false).show();worker.execute(()->{StringBuilder result=new StringBuilder();try(ExpertBackend backend=new ExpertBackend(this,false,address)){if(mode==0)result.append(w("ADB разрешён. Подтверждено подключение именно к этому устройству.","ADB authorized. Target verified as this device."));else{Map<String,Entry> available=services(this);LinkedHashSet<String> packages=new LinkedHashSet<>(),valid=new LinkedHashSet<>();for(String id:targets){Entry entry=available.get(id);if(entry==null)throw new java.io.IOException("Selected service is no longer installed: "+id);valid.add(id);packages.add(entry.pkg);}if(mode!=3&&Build.VERSION.SDK_INT>=33)for(String pkg:packages){RestrictedOps.grant(backend::shell,pkg,ExpertBackend.user(),Build.VERSION.SDK_INT);result.append(pkg).append(w(": ограничение снято, проверено\n",": restricted settings allowed and verified\n"));}if(mode==3){AccessibilitySettings.disable(backend::shell,valid,ExpertBackend.user());result.append(w("Выбранные службы отключены, состояние перечитано. Остальные службы сохранены.","Selected services are disabled and state was re-read. Other services were preserved."));}else if(mode==2){AccessibilitySettings.enable(backend::shell,valid,ExpertBackend.user());long until=System.currentTimeMillis()+6000;while(!frameworkEnabled(valid)&&System.currentTimeMillis()<until)Thread.sleep(150);if(!frameworkEnabled(valid))throw new java.io.IOException(w("Настройки записаны, но Android не подтвердил включение службы. Проверьте ограничения прошивки.","Settings were saved, but Android did not confirm enabled services. Check firmware restrictions."));result.append(w("Выбранные службы включены. Android подтвердил состояние; прежние службы сохранены.","Selected services are enabled. Android confirmed their state; existing services were preserved."));}else if(Build.VERSION.SDK_INT<33)result.append(w("На этой версии Android нет ограничения Android 13+. Для активации используйте «Включить через ADB».","This Android version has no Android 13+ restricted-settings gate. Use Enable through ADB to activate services."));}}catch(Exception e){result.append(w("Результат не подтверждён: ","Result not confirmed: ")).append(e.getMessage()).append(w("\nПроверьте сетевую отладку, адрес, RSA-запрос и инструкцию подключения.","\nCheck network debugging, address, RSA approval and the connection guide."));}main.post(()->{busy=false;if(isFinishing()||isDestroyed())return;progress.dismiss();progress=null;AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle(w("TV Access: результат","TV Access: result")).setMessage(result.toString());dialog.setPositiveButton("OK",null);AlertDialog shown=dialog.create();shown.setOnShowListener(v->shown.getButton(AlertDialog.BUTTON_POSITIVE).requestFocusFromTouch());shown.show();});});}
 protected void onResume(){super.onResume();if(!Ui.appearance(this).equals(appearance)){recreate();return;}Ui.bars(this);}
 protected void onSaveInstanceState(Bundle out){out.putStringArrayList("selected",new ArrayList<>(selected));super.onSaveInstanceState(out);}
 public void onBackPressed(){if(!busy)super.onBackPressed();}
 protected void onDestroy(){if(progress!=null)progress.dismiss();worker.shutdownNow();super.onDestroy();}
}
